// Static curriculum + kanji data (generated by scripts/, see README) and indexes over it.

export const isKanji = (ch) => /[㐀-䶿一-鿿豈-﫿]/u.test(ch);
// Distinct kanji the user has to know to write a word (々 just repeats the previous one).
export const kanjiOfWord = (word) => [...new Set([...word].filter(isKanji))];
export const kata2hira = (s) => s.replace(/[ァ-ヶ]/g, (c) => String.fromCharCode(c.charCodeAt(0) - 0x60));

// Card kinds per item: words get reading + writing cards, kanji-only items a kanji card.
export const cardKinds = (item) => (item.kanji ? ['k'] : ['r', 'w']);
export const cardIds = (item) => cardKinds(item).map((k) => `${item.id}#${k}`);

export function indexData(curriculum, kanjiList) {
  const items = curriculum.items;
  items.forEach((it, i) => { it.index = i; });
  const itemById = new Map(items.map((it) => [it.id, it]));
  const kanjiByChar = new Map(kanjiList.map((k, i) => [k.c, { ...k, index: i }]));
  const wordsByKanji = new Map();
  const itemsBySpelling = new Map();
  for (const it of items) {
    if (it.kanji) continue;
    for (const c of kanjiOfWord(it.word)) {
      if (!wordsByKanji.has(c)) wordsByKanji.set(c, []);
      wordsByKanji.get(c).push(it);
    }
    if (!itemsBySpelling.has(it.word)) itemsBySpelling.set(it.word, []);
    itemsBySpelling.get(it.word).push(it);
  }
  // Kanji introduced by an item (first word using it, or a kanji-only item).
  const introducedBy = new Map();
  for (const it of items) {
    const c = it.kanji || it.newKanji;
    if (c && !introducedBy.has(c)) introducedBy.set(c, it);
  }
  return { items, itemById, kanjiList: [...kanjiByChar.values()], kanjiByChar, wordsByKanji, itemsBySpelling, introducedBy };
}

export async function loadData(base = 'data/') {
  const [curriculum, kanji] = await Promise.all([
    fetch(base + 'curriculum.json').then((r) => r.json()),
    fetch(base + 'kanji.json').then((r) => r.json()),
  ]);
  return indexData(curriculum, kanji);
}

// Lessons = consecutive groups of `size` curriculum items. Progress is stored per item, so
// changing the size only regroups.
export function lessons(data, size) {
  const out = [];
  for (let i = 0; i < data.items.length; i += size) out.push(data.items.slice(i, i + size));
  return out;
}

// Readings of a kanji as plain hiragana stems (ひと.つ -> ひと, -び -> び).
export function kanjiReadings(k) {
  if (!k) return [];
  const out = new Set();
  for (const r of [...k.on, ...k.kun]) {
    const s = kata2hira(r).replace(/-/g, '').split('.')[0];
    if (s) out.add(s);
  }
  return [...out];
}
